    },
    {
      "concept_name": {
        "text": "Traditional AI vs Generative AI purpose",
        "refs": ["Q0011", "Q0012"],
        "claims": [
          {
            "text": "Traditional AI is used for classification, regression, and other tasks that analyze, predict, classify, or make decisions.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0011"],
            "related_refs": []
          },
          {
            "text": "Generative AI generates new content rather than just analyzing or predicting.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0012"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Traditional AI outputs labels or numbers; Generative AI outputs new content.",
        "refs": ["Q0012"],
        "claims": [
          {
            "text": "The type of output in traditional AI is usually yes/no labels, numbers, etc., whereas generative AI produces new content.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0012"],
