        "text": "Pre‑training in Generative AI",
        "refs": ["Q0013"],
        "claims": [
          {
            "text": "Generative AI models are pre‑trained on massive data sets such as all the text from the internet and books.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0013"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Pre‑training provides the knowledge base that enables generation of new content.",
        "refs": ["Q0013"],
        "claims": [
          {
            "text": "Whereas in GenAI, you do pre‑training on massive data set, you know, like all the texts from internet and books and so on.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0013"],
