        "text": "Capability comparison",
        "refs": ["Q0014"],
        "claims": [
          {
            "text": "Traditional AI has limited capabilities, whereas generative AI has high capabilities.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
